"use strict";
const { readFileSync } = require("node:fs");
const path = require("node:path");
const { JSDOM } = require("jsdom");
const ROOT = "/home/user/GoogleCalendarEventCreator";
const EXT = path.join(ROOT, "extension");
const { dataFile } = require(path.join(ROOT, "dev/requirements/extractor/data-files"));
const SOURCES = JSON.parse(readFileSync(path.join(EXT, "event-extractors/load-order.generated.json"), "utf8")).map((f) =>
  readFileSync(path.join(EXT, f), "utf8")
);
const name = process.argv[2];
const field = process.argv[3] || "description";
const url = readFileSync(dataFile(`${name}.url`), "utf8").trim();
const html = readFileSync(dataFile(`${name}.html`), "utf8");
const dom = new JSDOM(html, { url, runScripts: "outside-only" });
for (const src of SOURCES) dom.window.eval(src);
const custom = JSON.parse(dom.window.eval("JSON.stringify(GCal.extract())"));
dom.window.eval("GCal.sources = [];");
const bare = JSON.parse(dom.window.eval("JSON.stringify(GCal.extract())"));
const flat = (e) => (e ? { ...e, ...((e.times || [])[0] || {}) } : {});
const c = flat((custom.events || [])[0]);
const b = flat((bare.events || [])[0]);
console.log("--- CUSTOM " + field + " ---");
console.log(JSON.stringify(c[field]));
console.log("--- BARE " + field + " ---");
console.log(JSON.stringify(b[field]));

