1	// visit.tel-aviv.gov.il event pages: https://visit.tel-aviv.gov.il/Pages/EventLocation.aspx?ListType=Events&ItemId=2173
2	//
3	// Expected HTML input (simplified):
4	//
5	//   <h1 class="EventLocationTitle">Savta Stories - An Intergenerational Activity at the City Museum</h1>
6	//   <div class="EventLocationActivity">Jul 14-Aug 25, 2026</div>
7	//   <div class="EventLocationOpenHours">00:00-23:59</div>   (the structured OpeningTime)
8	//   <div class="EventLocationAddress">Bialik Street 27</div>
9	//   <div class="EventLocationAddress"><a href="...">City Museum Tel Aviv-Yafo</a></div>
10	//   <div class="EventLocationDescription">...description with &lt;br&gt; tags...</div>
11	//
12	//   JSON-LD (@type: Event) is present but its description contains raw newlines that
13	//   make JSON.parse() fail, so no JSON-LD fields are available via embeddedEvents.
14	//   All fields are read directly from the DOM.
15	//
16	// Where each field comes from:
17	//   title       h1.EventLocationTitle (bare h1 is a hidden "Event Location" header)
18	//   start       first date parsed from .EventLocationActivity ("Jul 14-Aug 25, 2026"),
19	//               carried to the day's opening time for a single-day event (see below)
20	//   end         second date parsed from .EventLocationActivity, or the opening-hours
21	//               closing time on the same single day
22	//   location    .EventLocationAddress a (venue name) + first .EventLocationAddress (street)
23	//   description .EventLocationDescription (block text, preserves <br> line breaks)
24	//   ctz         hardcoded Asia/Jerusalem (all events are in Tel Aviv, Israel)
25	//
26	// Opening hours / times (#508): the structured OpeningTime renders in
27	// .EventLocationOpenHours as "HH:MM-HH:MM" — "00:00-23:59" for an all-day run, or a
28	// real window like "10:00-14:00" for a timed event. text() reads the first match's
29	// textContent (Angular hides the unused copy via ng-hide, but textContent still
30	// returns it, so this works regardless of which copy is shown). A real window on a
31	// SINGLE-day event makes the start/end timed; the all-day sentinel and any
32	// multi-day run (applying one day's hours across the whole range would be wrong)
33	// stay an all-day date.
34	//
35	(() => {
36	  const { text, blockText, endFromTimeRange } = GCal;
37	
38	  // Parse the structured opening-hours window ("10:00-14:00") into { start, end }
39	  // "HH:MM" strings, or null when there's no real window: an absent/garbled value,
40	  // or the "00:00-23:59" all-day sentinel (which stays an all-day date).
41	  function parseOpeningHours(raw) {
42	    const m = (raw || "").match(/\b(\d{1,2}):(\d{2})\s*[-–—]\s*(\d{1,2}):(\d{2})\b/);
43	    if (!m) return null;
44	    const [sh, sm, eh, em] = m.slice(1).map(Number);
45	    if (sh > 23 || eh > 23 || sm > 59 || em > 59) return null;
46	    if (sh === 0 && sm === 0 && eh === 23 && em === 59) return null; // all-day sentinel
47	    const pad = (n) => String(n).padStart(2, "0");
48	    return { start: `${pad(sh)}:${pad(sm)}`, end: `${pad(eh)}:${pad(em)}` };
49	  }
50	
51	  // Parse a date-range string like "Jul 14-Aug 25, 2026" or "Jul 14, 2026".
52	  // Builds dates directly from parts to avoid new Date() timezone ambiguity.
53	  function parseDateRange(raw) {
54	    const MONTHS = {
55	      jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6,
56	      jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12,
57	    };
58	    const pad = (n) => String(n).padStart(2, "0");
59	    const fmt = (mon, day, yr) => {
60	      const mm = MONTHS[mon.slice(0, 3).toLowerCase()];
61	      return mm ? `${yr}-${pad(mm)}-${pad(+day)}` : "";
62	    };
63	    const m = (raw || "").match(
64	      /^(\w{3})\w*\s+(\d{1,2})(?:\s*[-–]\s*(\w{3})\w*\s+(\d{1,2}))?,?\s+(\d{4})/i
65	    );
66	    if (!m) return { start: "", end: "" };
67	    return {
68	      start: fmt(m[1], m[2], m[5]),
69	      end: m[3] ? fmt(m[3], m[4], m[5]) : "",
70	    };
71	  }
72	
73	  GCal.sources.push({
74	    name: "visit-tel-aviv",
75	    matches: (host) => /(^|\.)visit\.tel-aviv\.gov\.il$/.test(host),
76	    extract() {
77	      let { start, end } = parseDateRange(text(".EventLocationActivity"));
78	      // A single-day event (no date range) with a real opening-hours window
79	      // becomes timed: start carries to the opening time, end to the closing
80	      // time on the same day. A multi-day run or the all-day sentinel stays a
81	      // date (parseOpeningHours returns null for the sentinel). See #508.
82	      const hours = start && !end && parseOpeningHours(text(".EventLocationOpenHours"));
83	      if (hours) {
84	        start = `${start}T${hours.start}:00`;
85	        end = endFromTimeRange(`${hours.start}-${hours.end}`, start) || `${start.slice(0, 10)}T${hours.end}:00`;
86	      }
87	      // Venue name is in .EventLocationAddress a (inside the sidebar/tickets section);
88	      // street address is in the first .EventLocationAddress (plain text, no <a>).
89	      const venue = text(".EventLocationAddress a");
90	      const street = text(".EventLocationAddress");
91	      const location = [venue, street].filter(Boolean).join(", ");
92	      return {
93	        title: text("h1.EventLocationTitle"),
94	        start,
95	        end,
96	        location,
97	        description: blockText(document.querySelector(".EventLocationDescription")),
98	        ctz: "Asia/Jerusalem",
99	      };
100	    },
101	  });
102	})();
103

1	// Text-building helpers: turn a page's markup or structured fields into the
2	// strings the Calendar event should show. This is the generic machinery that
3	// used to live, reimplemented, inside individual sources.
4	//
5	// richText()/normalizeBlock()/blockText() render an element's markup — a source
6	// now only says WHICH element (and whether to keep bold), and these own HOW it
7	// renders: <br> becomes a newline, and (optionally) <strong>/<b> runs are kept
8	// as <b>…</b> so a heading stays bold in the Calendar details (which render as
9	// HTML); every other element contributes its text only.
10	//
11	// parts() assembles a comma-separated string (e.g. a location) from cleaned,
12	// de-duplicated pieces, so sources stop hand-rolling the same add/skip/join.
13	//
14	// Uses GCal.clean at call time. Augments globalThis.GCal (never replaces it) so
15	// load order can't clobber another file's contributions.
16	globalThis.GCal = Object.assign(globalThis.GCal || {}, (() => {
17	  // Serialize `el`'s content to text. `el` may be an Element or a CSS selector
18	  // (resolved against `root`, default document); a missing element yields "".
19	  // With { bold: true }, <strong>/<b> runs survive as <b>…</b>; otherwise only
20	  // their text is kept. No whitespace normalization is applied here — compose
21	  // with normalizeBlock (or your own per-line cleanup) when you need it.
22	  function richText(el, opts = {}, root) {
23	    if (typeof el === "string") el = (root || document).querySelector(el);
24	    if (!el) return "";
25	    let out = "";
26	    for (const node of el.childNodes) {
27	      if (node.nodeType === 3) {
28	        out += node.textContent;
29	      } else if (node.nodeType === 1) {
30	        const tag = node.tagName.toLowerCase();
31	        if (tag === "br") out += "\n";
32	        else if (opts.bold && (tag === "strong" || tag === "b")) out += `<b>${GCal.clean(node.textContent)}</b>`;
33	        else out += richText(node, opts);
34	      }
35	    }
36	    return out;
37	  }
38	
39	  // Tidy a rendered block: collapse horizontal whitespace (incl. &nbsp;) within
40	  // a line to single spaces, collapse runs of blank lines to a single blank
41	  // line, and trim. Newlines (e.g. from <br>) are preserved so the author's
42	  // line and paragraph breaks carry through to the Calendar details.
43	  function normalizeBlock(s) {
44	    return (s || "")
45	      .replace(/[^\S\n]+/g, " ")
46	      .replace(/\n{3,}/g, "\n\n")
47	      .trim();
48	  }
49	
50	  // The common case: render an element/selector and tidy it in one call.
51	  function blockText(el, opts, root) {
52	    return normalizeBlock(richText(el, opts, root));
53	  }
54	
55	  // Render an HTML *string* (e.g. a JSON-LD or inline-JSON description) to text,
56	  // preserving its <br>/newline layout instead of flattening it. The string is
57	  // page-controlled (untrusted), so parse it with DOMParser, which yields an
58	  // inert document — no browsing context, so scripts don't run, resources aren't
59	  // fetched, and event-handler attributes aren't realized — rather than assigning
60	  // to a live element's .innerHTML. The parsed <body> runs through blockText, so
61	  // no caller has to collapse a description down to a single line.
62	  function htmlToText(html, opts) {
63	    const body = new DOMParser().parseFromString(html || "", "text/html").body;
64	    return blockText(body, opts);
65	  }
66	
67	  // A small collector for building a comma-separated string (typically a
68	  // location) from several pieces: add() cleans each value and skips empties and
69	  // duplicates, then join() renders them. `equals(candidate, existing)` decides
70	  // what counts as a duplicate — default case-insensitive exact match; pass your
71	  // own (e.g. (a, b) => a === b for case-sensitive). `.list` is the live array,
72	  // so a caller can branch on what's been collected so far (e.g. only add a
73	  // fallback when nothing more specific was found). add() is chainable.
74	  function parts(equals) {
75	    const list = [];
76	    const same = equals || ((a, b) => a.toLowerCase() === b.toLowerCase());
77	    const api = {
78	      list,
79	      add(value) {
80	        value = GCal.clean(value == null ? "" : String(value));
81	        if (value && !list.some((p) => same(value, p))) list.push(value);
82	        return api;
83	      },
84	      join(sep) {
85	        return list.join(sep == null ? ", " : sep);
86	      },
87	    };
88	    return api;
89	  }
90	
91	  return { richText, normalizeBlock, blockText, htmlToText, parts };
92	})());
