const dom = new JSDOM(html, { url, runScripts: "outside-only" });
for (const src of SOURCES) dom.window.eval(src);
const w = dom.window;
const out = w.eval(`JSON.stringify({
  lang: document.documentElement.getAttribute("lang"),
  ogLocale: GCal.meta("og:locale"),
  ogTitle: GCal.meta("og:title"),
  ogSiteName: GCal.meta("og:site_name"),
  ogDesc: GCal.meta("og:description"),
  metaDesc: GCal.meta("description"),
  ogCountry: GCal.meta("og:country-name"),
  geoRegion: GCal.meta("geo.region"),
  ld: GCal.embeddedEvents.find(),
  itempropDesc: GCal.blockText('[itemprop="description"]'),
  h1: GCal.text("h1"),
})`);
const o = JSON.parse(out);
for (const [k, v] of Object.entries(o)) {
  let s = typeof v === "string" ? v : JSON.stringify(v);
