1	// barby.co.il event pages: https://barby.co.il/show/4401
2	//
3	// Expected HTML input (simplified):
4	//
5	//   <div class="showScreen">
6	//     <div class="show-card-body-2">
7	//       <h1 class="show-card-showname">אפרת גוש- הופעת בכורה לאלבום החדש</h1>
8	//       <div class="show-card-showdate">
9	//         <h4>16/06/2026 | שעת פתיחת דלתות: 21:00</h4>
10	//       </div>
11	//     </div>
12	//     <div class="show1-description">...event description HTML...</div>
13	//   </div>
14	//   <span id="footer-addres">הנמל 1 - נמל יפו</span>
15	//
16	// Where each field comes from:
17	//   title       h1.show-card-showname
18	//   start       div.show-card-showdate h4 text, parsed from "DD/MM/YYYY | ... HH:MM"
19	//               (Israeli day-first format, doors-opening time used as event start)
20	//   location    "בארבי" (fixed venue name) + footer span#footer-addres address
21	//   description div.show1-description (HTML rendered to text)
22	//   ctz         fixed to Asia/Jerusalem (Barby is in Tel Aviv)
23	//
24	(() => {
25	  const { text, blockText } = GCal;
26	
27	  // Parse "DD/MM/YYYY | שעת פתיחת דלתות: HH:MM" (Israeli day-first date).
28	  function parseBarbyDate(raw) {
29	    const m = (raw || "").match(/(\d{1,2})\/(\d{1,2})\/(\d{4})(?:.*?(\d{2}:\d{2}))?/);
30	    if (!m) return "";
31	    const [, d, mo, y, t] = m;
32	    const date = `${y}-${mo.padStart(2, "0")}-${d.padStart(2, "0")}`;
33	    return t ? `${date}T${t}:00` : date;
34	  }
35	
36	  GCal.sources.push({
37	    name: "barby",
38	    matches: (host) => /(^|\.)barby\.co\.il$/.test(host),
39	    extract() {
40	      const addr = text("#footer-addres");
41	      return {
42	        title: text("h1.show-card-showname"),
43	        start: parseBarbyDate(text(".show-card-showdate h4")),
44	        location: addr ? `בארבי, ${addr}` : "בארבי, הנמל 1, נמל יפו",
45	        description: blockText(".show1-description"),
46	        ctz: "Asia/Jerusalem",
47	      };
48	    },
49	  });
50	})();
